    if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(key)) throw new Error('Invalid Cypher map key');
    return key + ':' + literal(val);
  }).join(',') + '}';
  throw new Error('Unsupported Cypher value');
};
