ue, claim.source_field=value.source_field, claim.source_release=$release, claim.source_id='avonet', claim.taxonomy_release=$taxonomy_release, claim.inferred=value.inferred, claim.evidence_kind=value.evidence_kind, claim.summary_statistic=value.summary_statistic, claim.retrieved_at=$retrieved_at, claim.dataset_id=$dataset_id, claim.source_record_id=row.id, claim.policy_status='allowed' MERGE (claim)-[:ASSERTS_ABOUT]->(taxon) MERGE (claim)-[:SUPPORTED_BY]->(evidence) RETURN count(*) AS loaded_claims } CALL { WITH row,taxa WITH row,taxa WHERE size(taxa)<>1 MERGE (candidate:TaxonMappingCandidate {id:row.id+':candidate:'+$taxonomy_release}) SET candidate.source_scientific_name=row.scientific_name, candidate.source_taxonomy='HBW-BirdLife v5', candidate.taxonomy_release=$taxonomy_release, candidate.resolution_status='open', candidate.reason_code=CASE WHEN size(taxa)=0 THEN 'no_exact_match' ELSE 'ambiguous_exact_match' END, candidate.profile_json=row.profile_json, candidate.dataset_id=$dataset_id, candidate.source_record_id=row.id, candidate.policy_status='allowed', candidate.last_seen_run_id=$run_id, candidate.last_seen_at=$retrieved_at RETURN count(*) AS loaded_candidates } RETURN $batch_index AS batch_index, $batch_count AS batch_count, count(*) AS loaded_profiles, sum(loaded_claims) AS loaded_claims, sum(loaded_candidates) AS loaded_candidates, sum(CASE WHEN size(taxa)=1 THEN 1 ELSE 0 END) AS matched_profiles, sum(CASE WHEN size(taxa)=1 THEN size(row.claims) ELSE 0 END) AS expected_claims".replace(/\$([A-Za-z_][A-Za-z0-9_]*)/g, (_, key) => values[key]); })() }}

